use std::error::Error;
use std::fmt::Write as _;
use std::io::{self, Write};
use std::sync::mpsc;

use wgpu::util::DeviceExt;

/// One step of the stencil. Each invocation handles one cell and reads only
/// from `src`, so every cell sees the values left by the previous step.
/// Out-of-grid neighbours clamp to the edge cell itself.
const SHADER: &str = r#"
struct Params {
    width: u32,
    height: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
    let x = id.x;
    let y = id.y;
    if (x >= params.width || y >= params.height) {
        return;
    }

    let left = select(x - 1u, x, x == 0u);
    let right = select(x + 1u, x, x + 1u >= params.width);
    let up = select(y - 1u, y, y == 0u);
    let down = select(y + 1u, y, y + 1u >= params.height);

    let w = params.width;
    let centre = src[y * w + x];
    let sum = 4u * centre
        + src[y * w + left]
        + src[y * w + right]
        + src[up * w + x]
        + src[down * w + x];
    dst[y * w + x] = sum / 8u;
}
"#;

struct Input {
    width: u32,
    height: u32,
    steps: u32,
    cells: Vec<u32>,
}

fn parse_input(text: &str) -> Result<Input, Box<dyn Error>> {
    let mut tokens = text.split_ascii_whitespace();
    let mut next = |what: &str| -> Result<u64, Box<dyn Error>> {
        let token = tokens.next().ok_or_else(|| format!("missing {what}"))?;
        Ok(token.parse::<u64>().map_err(|e| format!("bad {what} {token:?}: {e}"))?)
    };

    let width = next("width")?;
    let height = next("height")?;
    let steps = next("steps")?;
    if !(1..=512).contains(&width) || !(1..=512).contains(&height) {
        return Err(format!("width and height must be in 1..=512, got {width}x{height}").into());
    }
    if steps > 1000 {
        return Err(format!("steps must be in 0..=1000, got {steps}").into());
    }

    let count = (width * height) as usize;
    let mut cells = Vec::with_capacity(count);
    for _ in 0..count {
        let value = next("cell")?;
        if value > 1_000_000 {
            return Err(format!("cell value {value} exceeds 1000000").into());
        }
        cells.push(value as u32);
    }

    Ok(Input {
        width: width as u32,
        height: height as u32,
        steps: steps as u32,
        cells,
    })
}

/// Runs `steps` stencil iterations on the GPU and returns the final grid.
fn run_on_gpu(input: &Input) -> Result<Vec<u32>, Box<dyn Error>> {
    let instance = wgpu::Instance::new(&wgpu::InstanceDescriptor::new_without_display_handle());
    let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
        power_preference: wgpu::PowerPreference::HighPerformance,
        ..Default::default()
    }))?;
    let (device, queue) = pollster::block_on(adapter.request_device(&wgpu::DeviceDescriptor::default()))?;

    let size = u64::from(input.width) * u64::from(input.height) * 4;

    let params = [input.width, input.height];
    let params_buf = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("params"),
        contents: bytemuck::cast_slice(&params),
        usage: wgpu::BufferUsages::UNIFORM,
    });

    // Two grids that swap roles each step: step k reads `grids[k % 2]` and
    // writes `grids[(k + 1) % 2]`.
    let grids = [0, 1].map(|i| {
        device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some(if i == 0 { "grid a" } else { "grid b" }),
            contents: bytemuck::cast_slice(&input.cells),
            usage: wgpu::BufferUsages::STORAGE | wgpu::BufferUsages::COPY_SRC,
        })
    });

    let readback = device.create_buffer(&wgpu::BufferDescriptor {
        label: Some("readback"),
        size,
        usage: wgpu::BufferUsages::MAP_READ | wgpu::BufferUsages::COPY_DST,
        mapped_at_creation: false,
    });

    let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("stencil layout"),
        entries: &[
            wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 1,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: true },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
            wgpu::BindGroupLayoutEntry {
                binding: 2,
                visibility: wgpu::ShaderStages::COMPUTE,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Storage { read_only: false },
                    has_dynamic_offset: false,
                    min_binding_size: None,
                },
                count: None,
            },
        ],
    });

    let bind_group = |src: &wgpu::Buffer, dst: &wgpu::Buffer| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("stencil bind group"),
            layout: &layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: params_buf.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: src.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: dst.as_entire_binding(),
                },
            ],
        })
    };
    let bind_groups = [
        bind_group(&grids[0], &grids[1]),
        bind_group(&grids[1], &grids[0]),
    ];

    let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
        label: Some("stencil"),
        source: wgpu::ShaderSource::Wgsl(SHADER.into()),
    });
    let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some("stencil pipeline layout"),
        bind_group_layouts: &[Some(&layout)],
        immediate_size: 0,
    });
    let pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
        label: Some("stencil pipeline"),
        layout: Some(&pipeline_layout),
        module: &module,
        entry_point: Some("main"),
        compilation_options: Default::default(),
        cache: None,
    });

    // Each compute pass finishes before the next begins, so a step's writes
    // are visible to the following step's reads.
    let mut encoder = device.create_command_encoder(&wgpu::CommandEncoderDescriptor {
        label: Some("heat"),
    });
    let groups_x = input.width.div_ceil(16);
    let groups_y = input.height.div_ceil(16);
    for step in 0..input.steps as usize {
        let mut pass = encoder.begin_compute_pass(&wgpu::ComputePassDescriptor {
            label: Some("stencil step"),
            timestamp_writes: None,
        });
        pass.set_pipeline(&pipeline);
        pass.set_bind_group(0, &bind_groups[step % 2], &[]);
        pass.dispatch_workgroups(groups_x, groups_y, 1);
    }

    let result = &grids[input.steps as usize % 2];
    encoder.copy_buffer_to_buffer(result, 0, &readback, 0, size);
    queue.submit(Some(encoder.finish()));

    let slice = readback.slice(..);
    let (tx, rx) = mpsc::channel();
    slice.map_async(wgpu::MapMode::Read, move |r| {
        let _ = tx.send(r);
    });
    device.poll(wgpu::PollType::wait_indefinitely())?;
    rx.recv()??;

    let data = slice.get_mapped_range();
    let out = bytemuck::cast_slice::<u8, u32>(&data).to_vec();
    drop(data);
    readback.unmap();
    Ok(out)
}

fn format_output(width: usize, cells: &[u32]) -> String {
    let mut out = String::new();
    let mut sum: u64 = 0;
    for row in cells.chunks(width) {
        for (i, value) in row.iter().enumerate() {
            if i > 0 {
                out.push(' ');
            }
            write!(out, "{value}").expect("writing to a String cannot fail");
            sum += u64::from(*value);
        }
        out.push('\n');
    }
    writeln!(out, "SUM {sum}").expect("writing to a String cannot fail");
    out
}

fn main() -> Result<(), Box<dyn Error>> {
    let path = std::env::args()
        .nth(1)
        .ok_or("usage: heat <input-file>")?;
    let text = std::fs::read_to_string(&path)?;
    let input = parse_input(&text)?;

    let cells = run_on_gpu(&input)?;
    let output = format_output(input.width as usize, &cells);

    let mut stdout = io::stdout().lock();
    stdout.write_all(output.as_bytes())?;
    stdout.flush()?;
    Ok(())
}

